public static void changeDevLanSearchProtocol(GlobalConfiguration.DeviceProtocolType deviceProtocolType) {
    if (deviceProtocolType == GlobalConfiguration.DeviceProtocolType.V380) {
        h = "NVDEVSEARCH^100";
        i = "NVDEVRESULT^100";
        j = "NVDEVRESULT^200";
        k = "NVDEVRESULT^300";
        l = "NVGROUPSEARCH^100^";
        m = "NVSEARCHRESULT^200";
        return;
    }
    if (deviceProtocolType == GlobalConfiguration.DeviceProtocolType.XVV) {
        h = "XVVSEARCH^100";
        i = "XVVRESULT^100";
        j = "XVVRESULT^200";
        k = "XVVRESULT^300";
        l = "XVVGROUPSEARCH^100^";
        m = "XVVSEARCHRESULT^200";
        return;
    }
    if (deviceProtocolType == GlobalConfiguration.DeviceProtocolType.SFV) {
        h = "SFVSEARCH^100";
        i = "SFVRESULT^100";
        j = "SFVRESULT^200";
        k = "SFVRESULT^300";
        l = "SFVGROUPSEARCH^100^";
        m = "SFVSEARCHRESULT^200";
        return;
    }
    if (deviceProtocolType == GlobalConfiguration.DeviceProtocolType.ICS) {
        h = "ICSSEARCH^100";
        i = "ICSRESULT^100";
        j = "ICSRESULT^200";
        k = "ICSRESULT^300";
        l = "ICSSGROUPSEARCH^100^";
        m = "ICSSGROUPSEARCH^200";
    }
}
